function gradeBlade(quality) {
  if (quality >= 90) {
    console.log("Masterwork");
  } else if (quality >= 70) {
    console.log("Fine");
  } else if (quality >= 50) {
    console.log("Serviceable");
  } else {
    console.log("Scrap");
  }
}

gradeBlade(72);

